// Reached by a bare specifier, so its package is the one its manifest names:
// `cstr`. It declares `abs` exactly as `probe` and the entry do, and `strlen`,
// which nothing else declares.
declare function abs(n: i32): i32;
declare function strlen(s: string): u64;

export const length = (s: string): u64 => strlen(s);

export const distance = (a: i32, b: i32): i32 => abs(a - b);
